@startuml

class Person {
  + personID : string
  + phoneNumber : string
  + keywords : string[]
}

class Institution {
  + institutionCode : string
}

class Article {
  + DOI : string
  + title : string
}

class PeerReviewedPaper extends Article {
  + citationCount : int
}

class TechnicalReport extends Article {}

class AuthorPosition {
  + position : int
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

Person "1" -- "*" Article : authors
Person "0..*" -- "0..*" Article : reviews
Person "*" -- "1" Institution : works for
Institution "1" -- "*" TechnicalReport : publishes
Institution "1" -- "*" Journal : subscribes to
Publisher "1" -- "*" Journal : publishes
Journal "1" -- "*" PeerReviewedPaper : publishes
Article "1" -- "*" AuthorPosition : has
Person "1" -- "*" AuthorPosition : in position

@enduml

